// Local built-app crash proof. Generated files only; no production hooks persist.
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {PDFDocument,PDFName,PDFString,PDFArray} from 'pdf-lib';
import {expect} from '@playwright/test';
import {launchReader} from '../tests/helpers/reader-launch.mjs';
import {readerRuntime} from '../tests/helpers/reader-runtime.mjs';
import {readerTools,closeReaderApp} from '../tests/helpers/reader-desktop.mjs';
import {ownedReceipt,stopOwned,drainOwned} from '../tests/helpers/reader-process-tree.mjs';

const root=await fs.mkdtemp(path.join(os.tmpdir(),'pdfix-pages-save-recovery-'));
const source=path.join(root,'original.pdf'),output=path.join(root,'recovered.pdf'),profile=path.join(root,'profile');
const report={scope:'Hidden built app; generated PDF; actual Pages save interrupted before publication, same-profile recovery, independent saved structure inspection',steps:[],errors:[]};
const hash=bytes=>createHash('sha256').update(bytes).digest('hex'),n=PDFName.of;
const pdf=await PDFDocument.create();for(let i=1;i<=3;i++)pdf.addPage([400,600]).drawText(`Recovery source sheet ${i}`,{x:40,y:520,size:15});
const c=pdf.context,pages=pdf.getPages(),note=c.register(c.obj({Type:'Annot',Subtype:'Text',Rect:[40,400,60,420],Contents:PDFString.of('Original recovery note'),PrivateAudit:PDFString.of('Keep exact')})),link=c.register(c.obj({Type:'Annot',Subtype:'Link',Rect:[40,450,190,475],Dest:[pages[1].ref,'Fit'],Border:[0,0,0]}));
pages[0].node.set(n('Annots'),c.obj([note,link]));const outline=c.register(c.obj({Type:'Outlines'})),chapter=c.register(c.obj({Title:PDFString.of('Second source sheet'),Parent:outline,Dest:[pages[1].ref,'Fit']}));c.lookup(outline).set(n('First'),chapter);c.lookup(outline).set(n('Last'),chapter);pdf.catalog.set(n('Outlines'),outline);
const original=Buffer.from(await pdf.save({useObjectStreams:false}));await fs.writeFile(source,original,{flag:'wx'});
const runtime=await readerRuntime();let app,page,timer;
const step=async(name,run)=>{await run();report.steps.push(name);await fs.writeFile(path.join(root,'report.json'),JSON.stringify(report,null,2));console.log('PASS '+name);};
async function launch(){app=await launchReader({args:[runtime],env:{...process.env,PDFIX_TEST_DATA:profile,PDFIX_TEST_VISIBLE:'0'}});page=await app.firstWindow();page.setDefaultTimeout(60000);page.on('pageerror',e=>report.errors.push(e.message));await app.evaluate(({dialog},file)=>{dialog.showOpenDialog=async()=>({canceled:false,filePaths:[file]});},source);await page.getByRole('button',{name:'Open a file',exact:true}).click();await expect(page.locator('.document-area .pdf-paper').first()).toHaveAttribute('data-ready','true');await readerTools(page,'Pages');return page.getByRole('region',{name:'Organize PDF pages',exact:true});}
async function destination(){await app.evaluate(({dialog},file)=>{dialog.showSaveDialog=async()=>({canceled:false,filePath:file});},output);}
try{
 timer=setTimeout(()=>{if(app)ownedReceipt(app).then(r=>stopOwned(r.processes)).catch(e=>console.error(e.message));},300000);
 let area;
 await step('Open generated annotated original and rearrange all pages',async()=>{area=await launch();for(const i of [3,2]){const button=area.getByRole('button',{name:`Move up output page ${i}`,exact:true});await expect(button).toBeEnabled();await button.click();}await expect(area.getByLabel('Output page 1 from source page 3',{exact:true})).toBeVisible();await expect(area.getByRole('status').filter({hasText:'Page arrangement saved locally.'})).toBeVisible();});
 await step('Pause the actual Pages save after 17 flushed staging bytes',async()=>{await destination();await app.evaluate((_electron,root)=>{const io=process.getBuiltinModule('node:fs/promises'),paths=process.getBuiltinModule('node:path'),open=io.open;io.open=async function(file,...args){const h=await open.call(this,file,...args);if(typeof file==='string'&&paths.dirname(file)===root&&paths.basename(file).startsWith('.pdfix-')&&file.endsWith('.partial'))h.writeFile=async bytes=>{await h.write(bytes.subarray(0,17));await h.sync();globalThis.pagesInterruptedStage=file;await new Promise(()=>{});};return h;};},root);await area.getByRole('button',{name:'Save pages',exact:true}).click();await expect.poll(()=>app.evaluate(()=>globalThis.pagesInterruptedStage),{timeout:120000}).toBeTruthy();report.stage=await app.evaluate(()=>globalThis.pagesInterruptedStage);expect((await fs.stat(report.stage)).size).toBe(17);await expect(fs.access(output)).rejects.toMatchObject({code:'ENOENT'});await page.screenshot({path:path.join(root,'interrupted-save.png')});});
 await step('Kill only the captured app main process and drain its owned children',async()=>{const receipt=await ownedReceipt(app),pid=await app.evaluate(()=>process.pid),main=receipt.processes.find(row=>row.pid===pid);if(!main||!['electron.exe','pdfix.exe'].includes(main.name.toLowerCase()))throw Error('Actual app main identity unavailable');expect(await stopOwned([main])).toContain(pid);report.crashCleanup=await drainOwned(receipt.processes);expect(report.crashCleanup.remaining).toEqual([]);app=null;});
 await step('Restart the same profile and restore the exact page arrangement',async()=>{area=await launch();await expect(area.getByRole('status').filter({hasText:/^Saved arrangement restored/})).toBeVisible();for(const [i,sourcePage]of [3,1,2].entries())await expect(area.getByLabel(`Output page ${i+1} from source page ${sourcePage}`,{exact:true})).toBeVisible();await page.screenshot({path:path.join(root,'restored-arrangement.png')});});
 await step('Save the recovered arrangement and independently inspect retained structures',async()=>{await destination();await area.getByRole('button',{name:'Save pages',exact:true}).click();await expect(area.getByRole('status').filter({hasText:/^Saved recovered.pdf/})).toBeVisible({timeout:120000});const saved=await PDFDocument.load(await fs.readFile(output),{updateMetadata:false});expect(saved.getPages().map(p=>p.ref.toString())).toEqual([pages[2],pages[0],pages[1]].map(p=>p.ref.toString()));const annotations=saved.getPage(1).node.lookup(n('Annots'),PDFArray);expect(annotations.asArray().map(r=>r.toString())).toEqual([note,link].map(r=>r.toString()));for(const ref of [note,link,outline,chapter])expect(saved.context.lookup(ref).toString()).toBe(c.lookup(ref).toString());const task=(await import('pdfjs-dist/legacy/build/pdf.mjs')).getDocument({data:new Uint8Array(await fs.readFile(output)),isEvalSupported:false,standardFontDataUrl:path.resolve('node_modules/pdfjs-dist/standard_fonts').split(path.sep).join('/')+'/'});try{const doc=await task.promise;for(const [i,sourcePage]of [3,1,2].entries())expect((await(await doc.getPage(i+1)).getTextContent()).items.map(v=>v.str).join(' ')).toContain(`Recovery source sheet ${sourcePage}`);}finally{await task.destroy();}expect(await fs.readFile(source)).toEqual(original);report.sourceSha256=hash(original);report.outputSha256=hash(await fs.readFile(output));report.retainedStructures=['Original comment/private field','Internal link/destination','Bookmark root/title/destination'];await area.getByRole('button',{name:'Close page workspace',exact:true}).click();await page.getByRole('button',{name:'Home',exact:true}).click();});
 report.pass=!report.errors.length;
}catch(error){report.pass=false;report.error=error.stack;if(page&&!page.isClosed()){report.status=await page.getByRole('status').allTextContents().catch(()=>[]);await page.screenshot({path:path.join(root,'failure.png')}).catch(()=>{});}}
finally{clearTimeout(timer);if(app){try{const receipt=await ownedReceipt(app);await closeReaderApp(app);report.closed=true;report.normalCleanup=await drainOwned(receipt.processes);if(report.normalCleanup.remaining.length||report.normalCleanup.forced.length)report.pass=false;}catch(e){report.pass=false;report.closeError=e.message;}}report.pass=!!(report.pass&&report.closed);await fs.writeFile(path.join(root,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({pass:report.pass,report:path.join(root,'report.json'),error:report.error}));if(!report.pass)process.exitCode=1;}
